package io.github.miklires.mevents.event;
import io.github.miklires.mevents.api.EventType;import java.util.List;
public record EventDefinition(String id,String displayName,EventType type,String world,int x,int y,int z,long preparationTicks,long durationTicks,String bossEntity,double bossHealth,List<RewardDefinition> rewards){public EventDefinition{if(id==null||id.isBlank())throw new IllegalArgumentException("Event id is blank");if(preparationTicks<0||durationTicks<1)throw new IllegalArgumentException("Invalid event duration");rewards=List.copyOf(rewards);if(rewards.isEmpty())throw new IllegalArgumentException("Event requires rewards");long distinct=rewards.stream().map(RewardDefinition::id).distinct().count();if(distinct!=rewards.size())throw new IllegalArgumentException("Duplicate reward id");}}
